import { GoogleGenAI, GenerateContentResponse, Chat, Modality } from "@google/genai";
import { EnhancementLevel } from '../types';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fileToGenerativePart = async (file: File) => {
  const base64EncodedDataPromise = new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: { data: await base64EncodedDataPromise, mimeType: file.type },
  };
};

export const generatePromptFromImage = async (imageFile: File): Promise<string> => {
    const imagePart = await fileToGenerativePart(imageFile);
    const textPart = {
        text: "You are an expert prompt engineer for generative art models. Describe this image in vivid detail. Focus on the subject, composition, lighting, artistic style, mood, and any specific visual elements. The description should be a complete and effective prompt that could be used to recreate a similar image. The final prompt should be detailed but concise, and kept under 3600 characters."
    };

    const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [imagePart, textPart] },
        config: {
            thinkingConfig: { thinkingBudget: 1024 },
            maxOutputTokens: 4624,
        }
    });

    return response.text;
};

export const generatePromptFromText = async (idea: string): Promise<string> => {
    const systemInstruction = "You are an expert prompt engineer for generative art models. A user has provided an idea. Your task is to expand this idea into a detailed and vivid prompt. Focus on creating a complete scene, describing the subject, composition, lighting, artistic style, mood, and other specific visual elements. The final prompt must be under 3600 characters. Do not include any conversational text, just output the generated prompt.";

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: idea,
        config: {
            systemInstruction: systemInstruction,
            thinkingConfig: { thinkingBudget: 1024 },
            maxOutputTokens: 4624,
        }
    });

    return response.text;
};


export const enhancePrompt = async(prompt: string, style: string, level: EnhancementLevel): Promise<string> => {
    let systemInstruction = "";
    const styleTag = style ? `[STYLE CONTEXT: ${style}]` : "[STYLE CONTEXT: Detailed Realism]";

    // "Before and After" Logic: 
    // We prepend the style context and append a strict final instruction.
    let userPrompt = `${styleTag}\n\nORIGINAL INPUT PROMPT:\n"""\n${prompt}\n"""\n\nTASK: Enhance the prompt above by rigorously applying and integrating the requested style.`;

    switch (level) {
        case 1:
            systemInstruction = "You are a prompt enhancement AI. Subtly improve the art prompt. Add minor details about lighting or composition. Keep changes minimal and true to the style. Output ONLY the resulting prompt.";
            break;
        case 3:
            systemInstruction = "You are a master prompt engineer. Drastically embellish the prompt. Invent and blend artistic styles, reference specific movements, and describe intricate technical details (camera angles, lens types, cinematic mood). Output ONLY the final prompt.";
            break;
        case 2:
        default:
            systemInstruction = "You are a technical prompt engineer. Make the prompt more evocative, detailed, and technically specific for high-end text-to-image models. Output ONLY the final prompt.";
            break;
    }

    userPrompt += `\n\nFINAL INSTRUCTION: Ensure the artistic style "${style || 'masterpiece quality'}" is the dominant aesthetic. The final output must be a single, cohesive art prompt under 3600 characters. No conversational filler.`;

    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: userPrompt,
        config: {
            systemInstruction: systemInstruction,
            thinkingConfig: { thinkingBudget: 2048 },
            maxOutputTokens: 5648, 
        }
    });

    return response.text;
};

export const generateInspirationalPrompt = async (): Promise<string> => {
    const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: "Based on current trending digital art on platforms like ArtStation, create one inspiring and detailed AI art prompt. The prompt should be ready to use in a text-to-image model. Be creative and describe a full, visually striking scene. Only output the prompt itself, with no conversational text.",
        config: {
            tools: [{googleSearch: {}}],
            thinkingConfig: { thinkingBudget: 1024 },
        },
    });

    return response.text;
};


export const generateImageFromPrompt = async (prompt: string, aspectRatio: string): Promise<string> => {
    const response = await ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: prompt,
        config: {
          numberOfImages: 1,
          outputMimeType: 'image/png',
          aspectRatio: aspectRatio,
        },
    });

    if (response.generatedImages && response.generatedImages.length > 0) {
        return response.generatedImages[0].image.imageBytes;
    }

    throw new Error("Image generation failed to produce an image.");
};

export const editImage = async (base64ImageData: string, mimeType: string, newPrompt: string): Promise<{ newImageBase64: string | null, textResponse: string | null }> => {
    const imagePart = {
      inlineData: {
        data: base64ImageData,
        mimeType: mimeType,
      },
    };
    const textPart = { text: newPrompt };

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          imagePart,
          textPart,
        ],
      },
      config: {
          systemInstruction: "You are an image editing AI. You will be given an image and a user request for changes. Your task is to return the edited image. You should also return a new, complete art prompt that reflects the changes you made to the image. Return *only* the new prompt in the text part of your response. Do not add any conversational text or markdown.",
          responseModalities: [Modality.IMAGE, Modality.TEXT],
      },
    });

    let newImageBase64: string | null = null;
    let textResponse: string | null = null;

    if (response.candidates && response.candidates.length > 0) {
        for (const part of response.candidates[0].content.parts) {
            if (part.text) {
                textResponse = part.text.trim();
            } else if (part.inlineData) {
                newImageBase64 = part.inlineData.data;
            }
        }
    }

    if (!newImageBase64) {
        textResponse = textResponse || "Image editing failed to produce a new image. The model may not have understood the request.";
    }

    return { newImageBase64, textResponse };
};

export const createChatSession = (): Chat => {
    return ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
            systemInstruction: "You are a prompt refinement AI. You will be given a main prompt to work on, and a user request for changes. Your task is to rewrite and return *only* the new, complete prompt that incorporates the user's request. Do not add any conversational text, introductions, or markdown formatting. Just output the modified prompt, which should be under 3600 characters.",
            thinkingConfig: { thinkingBudget: 1024 },
        },
    });
};

